function modal(title,body,submit,handler){const m=$('#modal');m.innerHTML=`<form id="dialog-form"><div class="modal-head"><h2>${title}</h2><button type="button" aria-label="關閉" id="close-modal">×</button></div><div class="modal-body">${body}<div id="form-error" class="error" role="alert"></div></div><div class="modal-foot"><button type="button" id="cancel-modal">${submit?'取消':'關閉'}</button>${submit?`<button class="primary" id="submit-modal" type="submit">${submit}</button>`:''}</div></form>`;$('#close-modal').onclick=$('#cancel-modal').onclick=()=>m.close();$('#dialog-form').onsubmit=async e=>{e.preventDefault();$('#form-error').textContent='';try{await handler(new FormData(e.target));}catch(err){$('#form-error').textContent=err.message||'操作未完成，請重試。';}};if(!m.open)m.showModal();}
function templateDownload(){if(!window.XLSX)return toast('Excel 元件尚未載入，請重新整理。');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['零件名稱','零件規格','需求數量'],['固定座','AL6061・100 × 50 mm',10],['外殼','鋁合金・黑色陽極',10],['軸承','608ZZ',20],['控制板','PCB Rev.A',10]]),'BOM');XLSX.writeFile(wb,'專案BOM範本.xlsx');}
function importDialog(){const p=project();if(!p||!isAdmin())return;let parsed=null;modal('匯入 Excel BOM',`<p>${esc(projectDate(p))} · ${esc(p.name)}<br>讀取第一個工作表，第 1 列需包含三個欄位。檔案留在本機解析。</p><button type="button" id="template" class="small">下載 Excel 範本</button><div class="upload section-gap"><label class="field" style="margin:0">選擇 Excel 檔案（.xlsx / .xls，限 5 MB）<input id="bom-file" type="file" accept=".xlsx,.xls" required></label></div><div id="import-preview" class="section-gap"></div><p class="data-note">欄位：零件名稱、零件規格（亦接受「規格」）、需求數量（每套）。匯入後可手動修改、刪除。數量需為正整數；同檔同名同規格視為重複，不會自動合併。</p>`,'確認匯入',()=>{if(!parsed)error('請先選擇有效的 Excel BOM 檔案。');for(const i of parsed){if(p.parts.some(x=>x.name===i.name&&x.spec===i.spec))error(`${i.name} 已存在，請改用表格修改，避免重複匯入。`);if(!Number.isSafeInteger(i.need*(p.defaultSets||1)))error('總需求超出可精確計算範圍。');}p.parts.push(...parsed.map(i=>({...i,id:crypto.randomUUID(),sets:p.defaultSets||1,received:0})));log(p,'匯入 BOM',`匯入 ${parsed.length} 項零件；各項依專案獨立建檔`);done(`已匯入 ${parsed.length} 項零件`);});$('#template').onclick=templateDownload;$('#bom-file').onchange=async e=>{parsed=null;$('#import-preview').innerHTML='';$('#form-error').textContent='';const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)error('檔案超過 5 MB，請改用較小的 BOM。');if(!window.XLSX)error('Excel 元件尚未載入，請重新整理。');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:''});const h=(rows[0]||[]).map(x=>String(x).trim()),ni=h.indexOf('零件名稱'),si=h.indexOf('零件規格')>=0?h.indexOf('零件規格'):h.indexOf('規格'),qi=h.indexOf('需求數量');if(ni<0||si<0||qi<0)error('第 1 列缺少必要欄位：零件名稱、零件規格、需求數量。');const out=[],seen=new Set(),errors=[];for(let r=1;r<rows.length;r++){const row=rows[r];if(row.every(c=>String(c).trim()===''))continue;const name=String(row[ni]??'').trim(),spec=String(row[si]??'').trim(),need=Number(row[qi]),key=JSON.stringify([name,spec]);if(!name||!spec||!Number.isSafeInteger(need)||need<=0||need>Number.MAX_SAFE_INTEGER){errors.push(`第 ${r+1} 列：名稱、規格不可空白，數量需為 正整數。`);continue;}if(seen.has(key)){errors.push(`第 ${r+1} 列：${name} 與規格重複，請先整理再匯入。`);continue;}seen.add(key);out.push({name,spec,need});}if(errors.length)error(errors.slice(0,8).join('\
'));if(!out.length)error('沒有可匯入的零件。');if(out.length>500)error('原型單一 BOM 上限為 500 項。');parsed=out;$('#import-preview').innerHTML=`<div class="notice">檢查通過，共 ${out.length} 項。確認後會建立這個專案專屬的零件清單。</div><div class="table-wrap"><table><thead><tr><th>零件名稱</th><th>規格</th><th>需求</th></tr></thead><tbody>${out.slice(0,8).map(i=>`<tr><td>${esc(i.name)}</td><td>${esc(i.spec)}</td><td>${i.need}</td></tr>`).join('')}</tbody></table></div>${out.length>8?'<p class="data-note">預覽前 8 項，確認後匯入全部項目。</p>':''}`;}catch(err){$('#form-error').textContent=err.message||'無法解析這個檔案，請檢查 Excel 格式。';}};}

const drafts={};
function migrateSimpleInventory(){for(const p of state.projects){if(!p.inventory){p.inventory={};for(const i of p.parts)p.inventory[i.id]=sum((p.baskets||[]).map(b=>qty(b.stock,i.id)));}if(p.location===undefined)p.location=[...new Set((p.baskets||[]).map(b=>b.slot).filter(Boolean))].join('、');p.archivedParts??=[];for(const i of p.parts)i.sets??=1;}}
function draftValue(p,i,key){return drafts[p.id]?.[`${key}:${i.id}`]??i[key];}
function captureDraft(){const form=$('#receipt-form'),p=project();if(form&&p)drafts[p.id]=Object.fromEntries(new FormData(form));}
function totalNeed(i){return i.need*(i.sets??1);}
function expanded(p){const d=drafts[p.id]||{};return `<div class="project-detail"><div class="detail-title"><h2>零件與收／領料</h2><button type="button" id="rename-project" class="small">修改專案名稱</button><button type="button" id="delete-project" class="small remove-part">刪除專案</button><button type="button" id="import-bom" class="small">匯入 Excel BOM</button><button type="button" id="add-part" class="small">＋ 手動新增零件</button>${p.archivedParts.length?'<button type="button" id="restore-part" class="small text-button">復原上次刪除</button>':''}</div><form id="receipt-form"><div class="form-grid">${locationFields(p.location,d.cabinet,d.shelf)}<label class="field">${esc(siteText('basketCountLabel'))}<input name="basketCount" value="${esc(d.basketCount??p.basketCount??1)}" type="number" min="1" step="1" required></label></div>${p.parts.length?`<div class="table-wrap"><table class="editable-bom"><thead><tr><th>零件名稱</th><th>規格</th><th>${esc(siteText('needLabel'))}</th><th>已收</th><th>${esc(siteText('setsLabel'))}</th><th>總需求量</th><th>現有庫存</th><th>本次收到</th><th>領料</th><th></th></tr></thead><tbody>${p.parts.map(i=>`<tr data-item="${esc(i.id)}"><td><input class="name-input" name="name:${esc(i.id)}" aria-label="${esc(i.name)}名稱" value="${esc(draftValue(p,i,'name'))}" maxlength="100" required></td><td><input class="spec-input" name="spec:${esc(i.id)}" aria-label="${esc(i.name)}規格" value="${esc(draftValue(p,i,'spec'))}" maxlength="200"></td><td><input class="qty demand-input" name="need:${esc(i.id)}" aria-label="${esc(i.name)}${esc(siteText('needLabel'))}" value="${esc(draftValue(p,i,'need'))}" type="number" min="0" step="1" required></td><td>${i.received}</td><td><input class="qty sets-input" name="sets:${esc(i.id)}" aria-label="${esc(i.name)}${esc(siteText('setsLabel'))}" value="${esc(draftValue(p,i,'sets'))}" type="number" min="1" step="1" required></td><td><output class="total-need">${Number(draftValue(p,i,'need'))*Number(draftValue(p,i,'sets'))}</output></td><td><strong>${inStock(p,i.id)}</strong></td><td><input class="qty" name="q:${esc(i.id)}" aria-label="${esc(i.name)}本次收到" value="${esc(d[`q:${i.id}`]??0)}" type="number" min="0" step="1" required></td><td><input class="qty" name="out:${esc(i.id)}" aria-label="${esc(i.name)}領料" value="${esc(d[`out:${i.id}`]??0)}" type="number" min="0" step="1" required></td><td><button type="button" class="small remove-part" data-remove="${esc(i.id)}" aria-label="刪除${esc(i.name)}">刪除</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">匯入 Excel BOM，或點「手動新增零件」開始。</div>'}<div class="receipt-controls"><p style="max-width:none">總需求量＝${esc(siteText('needLabel'))} × ${esc(siteText('setsLabel'))}。可超過需求收料，領料不得超過現有庫存（含本次收到）。</p><button class="primary" type="submit">儲存變更與收／領料</button></div><div id="receipt-error" class="error" role="alert"></div></form></div>`;}
function bindRows(){$('#rename-project')?.addEventListener('click',renameProject);$('#delete-project')?.addEventListener('click',deleteProjectDialog);document.querySelectorAll('[data-project]').forEach(el=>el.onclick=()=>{captureDraft();selectedId=selectedId===el.dataset.project?'':el.dataset.project;render();});$('#import-bom')?.addEventListener('click',()=>{captureDraft();importDialog();});$('#add-part')?.addEventListener('click',()=>{captureDraft();manualPart();});$('#restore-part')?.addEventListener('click',()=>{captureDraft();const p=project(),archived=p.archivedParts.pop();p.parts.splice(Math.min(archived.index,p.parts.length),0,archived.part);log(p,'復原零件',archived.part.name);render();toast('零件及原有數量已復原');});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{captureDraft();const p=project(),index=p.parts.findIndex(i=>i.id===el.dataset.remove);if(index<0)return;const i=p.parts.splice(index,1)[0];p.archivedParts.push({part:i,index});log(p,'刪除零件',`${i.name}；可復原，原有庫存紀錄保留`);render();toast('零件已刪除，可按「復原上次刪除」還原');});const form=$('#receipt-form');if(!form)return;form.oninput=e=>{captureDraft();const row=e.target.closest('tr');if(row){const total=Number(row.querySelector('.demand-input').value)*Number(row.querySelector('.sets-input').value);row.querySelector('.total-need').textContent=Number.isSafeInteger(total)&&total>=0?total:'—';}};form.onsubmit=e=>{e.preventDefault();const p=project();$('#receipt-error').textContent='';try{const fd=new FormData(form),seen=new Set();const changes=p.parts.map(i=>{const name=String(fd.get(`name:${i.id}`)||'').trim(),spec=String(fd.get(`spec:${i.id}`)||'').trim(),need=integer(fd.get(`need:${i.id}`),0,Number.MAX_SAFE_INTEGER),sets=integer(fd.get(`sets:${i.id}`),1,Number.MAX_SAFE_INTEGER),received=integer(fd.get(`q:${i.id}`),0,Number.MAX_SAFE_INTEGER),issued=integer(fd.get(`out:${i.id}`),0,Number.MAX_SAFE_INTEGER);if(!name)error('零件名稱不可空白。');const key=JSON.stringify([name,spec]);if(seen.has(key))error(`${name} 的名稱與規格重複，請確認。`);seen.add(key);if(!Number.isSafeInteger(need*sets)||!Number.isSafeInteger(i.received+received)||!Number.isSafeInteger(inStock(p,i.id)+received))error('數字超出可精確計算範圍，請縮小數量。');if(issued>inStock(p,i.id)+received)error(`${name} 可領 ${inStock(p,i.id)+received} 件（含本次收到），不能領出 ${issued} 件。`);return{i,name,spec,need,sets,received,issued};});const location=locationFromForm(fd);if(isAdmin())p.location=location;const basketCount=integer(fd.get('basketCount'),1,Number.MAX_SAFE_INTEGER);if(isAdmin())p.basketCount=basketCount;for(const c of changes){Object.assign(c.i,{name:c.name,spec:c.spec,need:c.need,sets:c.sets,received:c.i.received+c.received});p.inventory[c.i.id]=inStock(p,c.i.id)+c.received-c.issued;}const receivedItems=changes.filter(c=>c.received>0).map(c=>({name:c.name,qty:c.received})),issuedItems=changes.filter(c=>c.issued>0).map(c=>({name:c.name,qty:c.issued}));if(receivedItems.length||issuedItems.length){p.materialLogs??=[];p.materialLogs.unshift({id:crypto.randomUUID(),time:new Date().toISOString(),actor:actor(),received:receivedItems,issued:issuedItems});p.materialLogs=p.materialLogs.slice(0,2000);}log(p,'更新零件與收／領料',`${p.location||'未填位置'}；${siteText('basketCountLabel')} ${p.basketCount??p.defaultSets??1}；${changes.map(c=>`${c.name}：每套 ${c.need} × ${c.sets} 套；收到 ${c.received}／領出 ${c.issued}`).join('、')}`);delete drafts[p.id];render();toast('已儲存，總需求與庫存已更新');}catch(err){$('#receipt-error').textContent=err.message;}};}
function manualPart(){const p=project();modal('手動新增零件',`${field('零件名稱','name','','required maxlength="100"')}${field('規格（選填）','spec','','maxlength="200"')}<div class="form-grid">${field(esc(siteText('needLabel')),'need','1','type="number" min="0" step="1" required')}${field(esc(siteText('setsLabel')),'sets','1','type="number" min="1" step="1" required')}</div>`,'新增零件',fd=>{const name=fd.get('name').trim(),spec=fd.get('spec').trim(),need=integer(fd.get('need'),0,Number.MAX_SAFE_INTEGER),sets=integer(fd.get('sets'),1,Number.MAX_SAFE_INTEGER);if(!name)error('請填寫零件名稱。');if(!Number.isSafeInteger(need*sets))error('總需求超出可精確計算範圍。');if(p.parts.some(i=>i.name===name&&i.spec===spec))error('此名稱與規格已存在。');p.parts.push({id:crypto.randomUUID(),name,spec,need,sets,received:0});log(p,'手動新增零件',name);done('零件已新增，可直接在表格修改');});}
function newProject(){let count=1;const manualRow=n=>`<div class="manual-line">${field('零件名稱',`partname${n}`,'',n===0?'required maxlength="100"':'maxlength="100"')}${field('規格',`partspec${n}`,'','maxlength="200"')}${field(esc(siteText('needLabel')),`partneed${n}`,'1','type="number" min="0" step="1" required')}</div>`;modal('建立專案',`<div class="form-grid">${field(esc(siteText('projectIdLabel')),'projectDate','','type="date" required')}${field('專案名稱','name','','required maxlength="60"')}${locationFields()}${field(esc(siteText('basketCountLabel')),'basketCount','1','type="number" min="1" step="1" required')}${field(esc(siteText('setsLabel')),'sets','1','type="number" min="1" step="1" required')}</div><label class="field">零件建立方式<select id="entry-mode" name="mode"><option value="manual">手動輸入零件</option><option value="excel">匯入 Excel BOM</option></select></label><div id="manual-rows">${manualRow(0)}</div><button type="button" id="more-manual" class="small">＋ 再加一筆零件</button><p id="excel-hint" hidden>建立後會開啟 Excel 匯入視窗，需求數量視為${esc(siteText('needLabel'))}。</p>`,'建立專案',fd=>{const projectDate=String(fd.get('projectDate')||'').trim(),id=crypto.randomUUID(),name=fd.get('name').trim(),basketCount=integer(fd.get('basketCount'),1,Number.MAX_SAFE_INTEGER),sets=integer(fd.get('sets'),1,Number.MAX_SAFE_INTEGER),parts=[],seen=new Set();if(!/^\d{4}-\d{2}-\d{2}$/.test(projectDate))error('請選擇專案日期。');if(!name)error('請填寫專案名稱。');if(fd.get('mode')==='manual'){for(let n=0;n<count;n++){const pn=String(fd.get(`partname${n}`)||'').trim(),spec=String(fd.get(`partspec${n}`)||'').trim();if(!pn)error(`第 ${n+1} 筆請填寫零件名稱。`);const need=integer(fd.get(`partneed${n}`),0,Number.MAX_SAFE_INTEGER),key=JSON.stringify([pn,spec]);if(!Number.isSafeInteger(need*sets))error('總需求超出可精確計算範圍。');if(seen.has(key))error('零件名稱與規格重複。');seen.add(key);parts.push({id:crypto.randomUUID(),name:pn,spec,need,sets,received:0});}}const p={id,projectDate,name,owner:'',basketCount,location:locationFromForm(fd),defaultSets:sets,parts,inventory:{},archivedParts:[],baskets:[]};state.projects.unshift(p);selectedId=id;query='';log(p,'新增庫房管理紀錄',name);const excel=fd.get('mode')==='excel';done('專案已建立');if(excel)importDialog();});$('#more-manual').onclick=()=>$('#manual-rows').insertAdjacentHTML('beforeend',manualRow(count++));$('#entry-mode').onchange=e=>{const excel=e.target.value==='excel';$('#manual-rows').hidden=excel;$('#more-manual').hidden=excel;$('#excel-hint').hidden=!excel;$('#manual-rows').querySelectorAll('input').forEach(i=>i.disabled=excel);};}
function scopeDialog(){modal('個人試用版',`<p>庫房位置自行輸入，零件可用 Excel 匯入或手動新增，並可在表格修改或刪除；刪除可復原。</p><p>需求是每套數量。總需求量＝需求 × 套數。收料可超過總需求作為備料，領料扣除專案庫存。</p><div class="notice">資料保存在私人雲端，使用同一帳號可跨電腦載入。請定期從管理後台匯出備份。舊版多籃庫存已合併顯示為專案庫存，原始資料仍保留。</div>`,null);}

function deleteProjectDialog(){captureDraft();const p=project();if(!p)return;modal('刪除專案',`<p>確認刪除「<strong>${esc(p.name)}</strong>」（${esc(projectDate(p))}）？</p><p>此專案有 ${p.parts.length} 項零件、現有庫存 ${totalStock(p)} 件。刪除後將從清單移除，仍可從「已刪除專案」復原，包含零件、庫存與位置。</p>`,'確認刪除',()=>{const index=state.projects.indexOf(p);if(index<0)error('找不到這個專案。');state.deletedProjects??=[];state.deletedProjects.unshift({project:p,index,deletedAt:new Date().toISOString(),draft:drafts[p.id]||null});state.projects.splice(index,1);delete drafts[p.id];selectedId='';log(p,'刪除庫房管理紀錄','移至已刪除專案，可復原');done('專案已刪除，可從「已刪除專案」復原');});}
function deletedProjectsDialog(){captureDraft();modal('已刪除專案',`<p>復原會還原專案的零件、庫存及庫房位置。永久刪除後無法復原。</p>${(state.deletedProjects||[]).map((x,n)=>`<div class="deleted-project-row"><div><strong>${esc(x.project.name)}</strong><small>${esc(projectDate(x.project))} · ${x.project.parts.length} 項零件 · 庫存 ${totalStock(x.project)} 件</small></div><span><button type="button" class="small" data-restore-project="${n}">復原專案</button> <button type="button" class="small danger-button" data-purge-project="${n}">永久刪除</button></span></div>`).join('')||'<p>目前沒有已刪除專案。</p>'}`,null);document.querySelectorAll('[data-restore-project]').forEach(el=>el.onclick=()=>{const index=Number(el.dataset.restoreProject),entry=state.deletedProjects[index];if(!entry)return;if(state.projects.some(p=>p.id===entry.project.id)){$('#form-error').textContent='目前已有相同資料，無法復原。';return;}state.deletedProjects.splice(index,1);state.projects.splice(Math.min(entry.index,state.projects.length),0,entry.project);if(entry.draft)drafts[entry.project.id]=entry.draft;selectedId=entry.project.id;query='';log(entry.project,'復原專案','還原零件、庫存與位置');done('專案已復原');});document.querySelectorAll('[data-purge-project]').forEach(el=>el.onclick=async()=>{const index=Number(el.dataset.purgeProject),entry=state.deletedProjects[index];if(!entry||!confirm('確定永久刪除「'+entry.project.name+'」？零件、庫存、位置與收據圖片都會刪除，且無法復原。'))return;el.disabled=true;try{const response=await apiFetch('/api/receipts?project='+encodeURIComponent(entry.project.id),{method:'DELETE'}),data=await response.json();if(!response.ok)error(data.error||'收據圖片刪除失敗');addAudit('永久刪除庫房管理紀錄',entry.project.name,'庫房管理 > 已刪除專案',entry.project.id);state.deletedProjects.splice(index,1);persist();deletedProjectsDialog();toast('專案已永久刪除');}catch(err){el.disabled=false;$('#form-error').textContent=err.message||'永久刪除未完成。';}});}

const siteTextFields=[
 ['casesTitle','案件管理區標題','案件管理',60,true],
 ['casesDescription','案件管理區說明','查看案件進度、廠商與日期',120,false],
 ['auditTitle','資訊庫標題','資訊庫',60,true],
 ['auditDescription','資訊庫說明','記錄案件、庫房與照片的操作時間',160,false],
 ['projectIdLabel','原「專案編號」欄位名稱','專案日期',40,true],
 ['basketCountLabel','籃數欄位名稱','籃數',40,true],
 ['setsLabel','套數欄位名稱','套數',40,true],
 ['needLabel','每套需求欄位名稱','每套需求',40,true],
 ['badge','網站名稱旁標籤','簡易版',40,false],
 ['banner','首頁提示文字','私人雲端庫房 · 同一帳號跨電腦使用',200,false],
 ['bannerBadge','提示列右側文字','雲端版',40,false],
 ['brand','網站名稱','專案庫房',60,true],
 ['heading','首頁大標題','收料入庫，領料扣庫存。',100,true],
 ['description','標題下方說明','點開專案，直接登記收料、庫房位置與領料。',300,false],
 ['listTitle','專案清單標題','專案清單',60,true],
 ['footer','頁尾說明','同名零件依專案分開記錄 · 收料增加庫存，領料扣除庫存',300,false]
];
function siteText(key){const stored=state.siteText?.[key];if(key==='basketCountLabel')return stored??state.siteText?.setsLabel??'籃數';if(key==='setsLabel'&&(!stored||stored==='籃數'))return '套數';if(key==='needLabel'&&(!stored||stored==='每籃需求'))return '每套需求';return stored??siteTextFields.find(f=>f[0]===key)[2];}
function saveEditState(candidate){
 try{localStorage.setItem('project-warehouse-v1',JSON.stringify(candidate));}
 catch{error('無法儲存，請確認瀏覽器允許網站儲存資料後再試。');}
 state=candidate;
}
function editSiteText(){
 captureDraft();
 modal('編輯網站文字','<p>修改後按「儲存文字」，會保存在私人雲端。</p>'+siteTextFields.map(([key,label,value,max,required])=>field(label,key,siteText(key),'maxlength="'+max+'" '+(required?'required':''))).join(''),'儲存文字',fd=>{
  const text={};
  for(const [key,label,value,max,required] of siteTextFields){
   text[key]=String(fd.get(key)??'').trim();
   if(required&&!text[key])error('請填寫'+label+'。');
   if(text[key].length>max)error(label+'最多 '+max+' 字。');
  }
  addAudit('修改網站文字','更新可自訂標題與說明','管理後台 > 網站文字');
  saveEditState({...state,siteText:{...state.siteText,...text}});
  done('網站文字已儲存');
 });
}
function renameProject(){
 captureDraft();const p=project();if(!p)return;
 modal('修改專案名稱',field('專案名稱','name',p.name,'required maxlength="60"'),'儲存名稱',fd=>{
  const name=String(fd.get('name')??'').trim();
  if(!name||name.length>60)error('專案名稱請填寫 1–60 字。');
  const candidate={...state,projects:state.projects.map(x=>x.id===p.id?{...x,name}:x),logs:[{time:new Date().toISOString(),project:p.id,actor:actor(),action:'修改專案名稱',detail:p.name+' → '+name},...(state.logs||[])]};
  saveEditState(candidate);query='';done('專案名稱已儲存');
 });
}

